mapper.select:

where p.del_flag = '0'

    and p.category_id = #{categoryId}


    and p.plant_name like concat('%', #{plantName}, '%')


    and p.difficulty_level = #{difficultyLevel}


    and p.price_level = #{priceLevel}


    and p.pet_safe_flag = #{petSafeFlag}


    and p.display_status = #{displayStatus}


    and p.status = #{status}

order by p.sort_num, p.plant_id desc

mapper.update:
update zx_plant
category_id = #{categoryId}, plant_name = #{plantName}, plant_code = #{plantCode}, alias_name = #{aliasName}, cover_image = #{coverImage}, plant_summary = #{plantSummary}, difficulty_level = #{difficultyLevel}, price_level = #{priceLevel}, display_status = #{displayStatus}, pet_safe_flag = #{petSafeFlag}, purge_effect_flag = #{purgeEffectFlag}, aroma_flag = #{aromaFlag}, suitable_scene = #{suitableScene}, sort_num = #{sortNum}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where plant_id = #{plantId}

update zx_plant
set display_status = #{displayStatus}, update_by = #{updateBy}, update_time = sysdate()
where plant_id = #{plantId}
